        let path = logs_dir.join("boot-trace.log");
        let oversized = "x".repeat((BOOT_TRACE_LOG_MAX_BYTES + 1) as usize);
        std::fs::write(&path, &oversized).unwrap();
        assert!(std::fs::metadata(&path).unwrap().len() > BOOT_TRACE_LOG_MAX_BYTES);

