    fn setup_dirty_inplace_delivery_run(
        conn: &rusqlite::Connection,
        repo: &std::path::Path,
        session_id: &str,
        run_id: &str,
        local: bool,
    ) {
        init_test_repo(repo);
        if local {
            conn.execute(
                "UPDATE repos SET path = ?1 WHERE id = 'local-default'",
                [repo.to_str().unwrap()],
            )
            .unwrap();
            db::create_session(conn, session_id, "Local", "local-default", "local").unwrap();
        } else {
            namespaces_repo::add_namespace(
                conn,
                "ns-inplace-delivery",
                "github_org",
                "Delivery",
                0,
            )
            .unwrap();
            repos_repo::add_repo(
                conn,
                "repo-inplace-delivery",
                "ns-inplace-delivery",
                "github",
                Some("owner"),
                "repo",
                repo.to_str().unwrap(),
                None,
            )
            .unwrap();
            db::create_session(
                conn,
                session_id,
                "GitHub",
                "repo-inplace-delivery",
                "ns-inplace-delivery",
            )
            .unwrap();
        }
        checkpoint::CheckpointStore::new(conn)
            .unwrap()
            .record_preimage(session_id, run_id, repo, &repo.join("seed.md"))
            .unwrap();
        std::fs::write(repo.join("seed.md"), "uncommitted agent change\n").unwrap();
    }

