    /// Slice B Task B2：staging_diff_stats 返「停在 staging、未落地」的本轮改动统计。
    /// 有 merge_candidate(merged_sha=staged) → Some(files/+/-)；无 merge_candidate 的 run → None。
    #[test]
    fn staging_diff_stats_returns_counts_when_merged_into_staging() {
        let conn = rusqlite::Connection::open_in_memory().unwrap();
        crate::db::init_schema(&conn).unwrap();
        let tmp = tempfile::tempdir().unwrap();
        let repo = tmp.path();
        let git = |args: &[&str]| {
            let output = std::process::Command::new("git")
                .current_dir(repo)
                .args(args)
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "git {:?} failed: {}",
                args,
                String::from_utf8_lossy(&output.stderr)
            );
        };
        git(&["init", "-q"]);
        git(&["config", "user.email", "t@t"]);
        git(&["config", "user.name", "t"]);
        git(&["config", "commit.gpgsign", "false"]);
        std::fs::write(repo.join("base.txt"), "base\n").unwrap();
        git(&["add", "."]);
        git(&["commit", "-qm", "base"]);
        let pre = crate::worktree::rev_parse_head(repo).unwrap();
        // staging 分支：在 base 上加一个改动 commit（新增 README.md 三行）。
        git(&["branch", "agentloom/run/r1"]);
        git(&["switch", "-q", "agentloom/run/r1"]);
        std::fs::write(repo.join("README.md"), "a\nb\nc\n").unwrap();
        git(&["add", "."]);
        git(&["commit", "-qm", "artifact"]);
        let staged = crate::worktree::rev_parse_head(repo).unwrap();
        git(&["switch", "-q", "-"]);

        namespaces_repo::add_namespace(&conn, "ns1", "github_org", "ns1", 0).unwrap();
        repos_repo::add_repo(
            &conn,
            "repo1",
            "ns1",
            "github",
            None,
            "repo1",
            repo.to_str().unwrap(),
            None,
        )
        .unwrap();
        crate::db::create_session(&conn, "s1", "GitHub", "repo1", "ns1").unwrap();
        crate::db::insert_artifact(
            &conn,
            &crate::db::Artifact {
                id: "art-1".into(),
                session_id: "s1".into(),
                run_id: "r1".into(),
                member_assignment_id: "a1".into(),
                branch: "agentloom/s1-m-a1".into(),
                base_sha: pre.clone(),
                commit_sha: Some(staged.clone()),
                files_changed: 1,
                state: "merged".into(),
                created_at: 1,
            },
        )
        .unwrap();
        // 额外 seed 一条 merge_candidate（merged 进 staging·merged_sha=staged）。
        crate::db::upsert_merge_candidate(
            &conn,
            &crate::db::MergeCandidate {
                id: "mc-1".into(),
                artifact_id: "art-1".into(),
                staging_branch: "agentloom/run/r1".into(),
                state: "merged".into(),
                merged_sha: Some(staged.clone()),
                created_at: 1,
            },
        )
        .unwrap();

        let db = crate::db::Db(crate::perf_probe::TimedMutex::new(conn));
        let stats = staging_diff_stats_inner(&db.0.lock().unwrap(), "s1", "r1")
            .unwrap()
            .expect("已 merge 进 staging 应有统计");
        assert_eq!(stats.files, 1, "改了 1 个文件");
        assert_eq!(stats.insertions, 3, "新增 3 行");
        assert_eq!(stats.deletions, 0, "删 0 行");

        // 无 merge_candidate 的 run（连 artifact 都没有）→ None。
        let none = staging_diff_stats_inner(&db.0.lock().unwrap(), "s1", "r-absent").unwrap();
        assert!(none.is_none(), "无 merge_candidate 的 run 应返 None");
    }

    /// ④ D32 卫生：apply 落地后必须收尾清 agentloom/* 命名空间——
    /// 删本轮 staging 分支 `agentloom/run/<run>` + 逐成员清 member worktree/分支/base ref。
    /// 现状（修前）：apply 只 ff-merge + 记 LandingCommit，命名空间分支全留 → D32 违反。
    #[test]
    fn apply_run_cleans_staging_and_member_workspaces() {
        let _home_env_guard = crate::worktree::test_home_lock();
        let home = tempfile::tempdir().unwrap();
        let old = std::env::var_os("HOME");
        std::env::set_var("HOME", home.path());

        let conn = rusqlite::Connection::open_in_memory().unwrap();
        crate::db::init_schema(&conn).unwrap();
        // 用户 repo（落地目标）落在 HOME 外的独立 tempdir。
        let tmp = tempfile::tempdir().unwrap();
        let repo = tmp.path().join("repo");
        std::fs::create_dir_all(&repo).unwrap();
        let git = |args: &[&str]| {
            let output = std::process::Command::new("git")
                .current_dir(&repo)
                .args(args)
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "git {:?} failed: {}",
                args,
                String::from_utf8_lossy(&output.stderr)
            );
        };
        git(&["init", "-q"]);
        git(&["config", "user.email", "t@t"]);
        git(&["config", "user.name", "t"]);
        git(&["config", "commit.gpgsign", "false"]);
        crate::worktree::mark_test_app_domain(&repo);
        std::fs::write(repo.join("base.txt"), "base\n").unwrap();
        git(&["add", "."]);
        git(&["commit", "-qm", "base"]);
        let pre = crate::worktree::rev_parse_head(&repo).unwrap();
        // staging 分支 agentloom/run/r1 = base + 1 提交（模拟 merge_artifact_to_staging 产物）。
        git(&["branch", "agentloom/run/r1"]);
        git(&["switch", "-q", "agentloom/run/r1"]);
        std::fs::write(repo.join("README.md"), "changed\n").unwrap();
        git(&["add", "."]);
        git(&["commit", "-qm", "artifact"]);
        let staged = crate::worktree::rev_parse_head(&repo).unwrap();
        git(&["switch", "-q", "-"]);

        // 真实建一个 member 工作区（branch agentloom/s1-m-a1 + base ref + worktree）。
        let member_wt =
            crate::worktree::ensure_member_workspace("s1", "a1", Some(&repo), false).unwrap();
        assert!(member_wt.exists(), "member worktree 应已建");
        let ref_exists = |r: &str| {
            std::process::Command::new("git")
                .current_dir(&repo)
                .args(["rev-parse", "--verify", "--quiet", r])
                .output()
                .map(|o| o.status.success())
                .unwrap_or(false)
        };
        assert!(
            ref_exists("refs/heads/agentloom/run/r1"),
            "staging 分支应在"
        );
        assert!(
            ref_exists("refs/heads/agentloom/s1-m-a1"),
            "member 分支应在"
        );
        assert!(
            ref_exists("refs/agentloom/base/s1-m-a1"),
            "member base ref 应在"
        );

        namespaces_repo::add_namespace(&conn, "ns1", "github_org", "ns1", 0).unwrap();
        repos_repo::add_repo(
            &conn,
            "repo1",
            "ns1",
            "github",
            None,
            "repo1",
            repo.to_str().unwrap(),
            None,
        )
        .unwrap();
        crate::db::create_session(&conn, "s1", "GitHub", "repo1", "ns1").unwrap();
        crate::db::insert_team_run_pending(
            &conn,
            "s1",
            "r1",
            "目标",
            "lead-1",
            r#"[{"assignment_id":"a1"}]"#,
        )
        .unwrap();
        crate::db::insert_artifact(
            &conn,
            &crate::db::Artifact {
                id: "art-1".into(),
                session_id: "s1".into(),
                run_id: "r1".into(),
                member_assignment_id: "a1".into(),
                branch: "agentloom/s1-m-a1".into(),
                base_sha: pre.clone(),
                commit_sha: Some(staged.clone()),
                files_changed: 1,
                state: "merged".into(),
                created_at: 1,
            },
        )
        .unwrap();

        let landed = apply_run_to_current_branch_inner(&conn, "s1", "r1").unwrap();
        assert_eq!(landed, staged, "ff-merge 落地点不变");

        // D32 收尾：命名空间分支/worktree 全清。
        assert!(
            !ref_exists("refs/heads/agentloom/run/r1"),
            "落地后应删 staging 分支"
        );
        assert!(
            !ref_exists("refs/heads/agentloom/s1-m-a1"),
            "落地后应删 member 分支"
        );
        assert!(
            !ref_exists("refs/agentloom/base/s1-m-a1"),
            "落地后应删 member base ref"
        );
        assert!(!member_wt.exists(), "落地后应删 member worktree 目录");

        match old {
            Some(v) => std::env::set_var("HOME", v),
            None => std::env::remove_var("HOME"),
        }
    }

    // ===== T3：撤销自动落地（Local 就地 + repo + 守卫）=====

    /// 建 Local 就地会话 + 真 git 项目目录，落一笔改动 commit + 记 LandingCommit + merged artifact。
    /// 返回 (项目目录, pre_head, landed_head, artifact_id)。调用方须先 set HOME 并持 test_home_lock。
    fn setup_local_landed(
        conn: &rusqlite::Connection,
        project: &std::path::Path,
    ) -> (String, String, String) {
        let git = |args: &[&str]| {
            let out = std::process::Command::new("git")
                .current_dir(project)
                .args(args)
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "git {:?}: {}",
                args,
                String::from_utf8_lossy(&out.stderr)
            );
        };
        git(&["init", "-q"]);
        git(&["config", "user.email", "t@t"]);
        git(&["config", "user.name", "t"]);
        git(&["config", "commit.gpgsign", "false"]);
        std::fs::write(project.join("base.txt"), "base\n").unwrap();
        git(&["add", "."]);
        git(&["commit", "-qm", "base"]);
        let pre = crate::worktree::rev_parse_head(project).unwrap();

        // worker 改动 → 落地 commit。
        std::fs::write(project.join("landed.txt"), "from run\n").unwrap();
        git(&["add", "."]);
        git(&["commit", "-qm", "landed"]);
        let landed = crate::worktree::rev_parse_head(project).unwrap();

        db::create_session(conn, "s1", "t", "local-default", "local").unwrap();
        conn.execute(
            "UPDATE repos SET path = ?1 WHERE id = 'local-default'",
            [project.to_str().unwrap()],
        )
        .unwrap();
        crate::db::insert_artifact(
            conn,
            &crate::db::Artifact {
                id: "art-1".into(),
                session_id: "s1".into(),
                run_id: "r1".into(),
                member_assignment_id: "a1".into(),
                branch: "agentloom/a1".into(),
                base_sha: pre.clone(),
                commit_sha: Some(landed.clone()),
                files_changed: 1,
                state: "merged".into(),
                created_at: 1,
            },
        )
        .unwrap();
        crate::db::insert_landing_commit(
            conn,
            &crate::db::LandingCommit {
                id: "lc-1".into(),
                session_id: "s1".into(),
                run_id: "r1".into(),
                artifact_id: Some("art-1".into()),
                pre_head: pre.clone(),
                landed_head: landed.clone(),
                commit_count: 1,
                files_changed: 1,
                insertions: 1,
                deletions: 0,
                created_at: crate::db::now_secs(),
            },
        )
        .unwrap();
        (pre, landed, "art-1".into())
    }
    fn setup_local_landed_multiline(
        conn: &rusqlite::Connection,
        project: &std::path::Path,
    ) -> (String, String) {
        let git = |args: &[&str]| {
            let out = std::process::Command::new("git")
                .current_dir(project)
                .args(args)
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "git {:?}: {}",
                args,
                String::from_utf8_lossy(&out.stderr)
            );
        };
        git(&["init", "-q"]);
        git(&["config", "user.email", "t@t"]);
        git(&["config", "user.name", "t"]);
        git(&["config", "commit.gpgsign", "false"]);
        std::fs::write(project.join("base.txt"), "l1\nl2\nl3\n").unwrap();
        git(&["add", "."]);
        git(&["commit", "-qm", "base"]);
        let pre = crate::worktree::rev_parse_head(project).unwrap();

        // worker 改动：改 base.txt（删 1 改 → 实际 +2/-1）+ 新增多行文件（+3）。
        std::fs::write(project.join("base.txt"), "l1\nX2\nl3\nl4\n").unwrap();
        std::fs::write(project.join("added.txt"), "a1\na2\na3\n").unwrap();
        git(&["add", "."]);
        git(&["commit", "-qm", "landed"]);
        let landed = crate::worktree::rev_parse_head(project).unwrap();

        db::create_session(conn, "s1", "t", "local-default", "local").unwrap();
        conn.execute(
            "UPDATE repos SET path = ?1 WHERE id = 'local-default'",
            [project.to_str().unwrap()],
        )
        .unwrap();
        crate::db::insert_artifact(
            conn,
            &crate::db::Artifact {
                id: "art-1".into(),
                session_id: "s1".into(),
                run_id: "r1".into(),
                member_assignment_id: "a1".into(),
                branch: "agentloom/a1".into(),
                base_sha: pre.clone(),
                commit_sha: Some(landed.clone()),
                files_changed: 2,
                state: "merged".into(),
                created_at: 1,
            },
        )
        .unwrap();
        // T2 的缺口：行数存 0（record_inplace_artifact_landing 写 insertions:0/deletions:0）。
        crate::db::insert_landing_commit(
            conn,
            &crate::db::LandingCommit {
                id: "lc-1".into(),
                session_id: "s1".into(),
                run_id: "r1".into(),
                artifact_id: Some("art-1".into()),
                pre_head: pre.clone(),
                landed_head: landed.clone(),
                commit_count: 1,
                files_changed: 2,
                insertions: 0,
                deletions: 0,
                created_at: crate::db::now_secs(),
            },
        )
        .unwrap();
        (pre, landed)
    }

    #[test]
    fn run_landing_info_returns_landed_head_and_recomputes_local_line_counts() {
        let _home = crate::worktree::test_home_lock();
        let tmp = tempfile::tempdir().unwrap();
        let old = std::env::var_os("HOME");
        std::env::set_var("HOME", tmp.path());

        let conn = crate::test_support::mem_db();
        let project = tmp.path().join("local-default");
        std::fs::create_dir_all(&project).unwrap();
        let (pre, landed) = setup_local_landed_multiline(&conn, &project);

        let info = run_landing_info_inner(&conn, "s1", "r1")
            .unwrap()
            .expect("Local 已落地应有 landing info");

        // landed_head = 真 git sha（不是 artifact_id / run-…）。
        assert_eq!(info.landed_head, landed, "应返回真 landed_head sha");
        assert_eq!(info.pre_head, pre, "应返回 pre_head sha");
        assert_eq!(info.files_changed, 2, "改了 2 个文件");

        // 关键：行数从项目目录 pre..landed numstat **重算**·补 T2 缺口（存的是 0）。
        // base.txt：+2/-1（l2→X2 改一行算删 1 增 1·加 l4 增 1）；added.txt：+3/-0。
        assert_eq!(info.insertions, 5, "重算 insertions（非存的 0）");
        assert_eq!(info.deletions, 1, "重算 deletions（非存的 0）");

        // 改动文件列表（per-file 行数·读项目目录）。
        let paths: Vec<&str> = info.files.iter().map(|f| f.path.as_str()).collect();
        assert!(paths.contains(&"base.txt"), "含 base.txt：{paths:?}");
        assert!(paths.contains(&"added.txt"), "含 added.txt：{paths:?}");
        let added = info.files.iter().find(|f| f.path == "added.txt").unwrap();
        assert_eq!(
            (added.insertions, added.deletions),
            (3, 0),
            "added.txt +3/-0"
        );

        match old {
            Some(v) => std::env::set_var("HOME", v),
            None => std::env::remove_var("HOME"),
        }
    }

