    fn review_file<'a>(review: &'a worktree::Review, path: &str) -> &'a worktree::ReviewFile {
        review
            .files
            .iter()
            .find(|file| file.path == path)
            .unwrap_or_else(|| panic!("Review 缺文件 {path}：{}", review.patch))
    }

