    fn msg(role: &str, text: &str, engine: Option<&str>) -> db::Message {
        db::Message {
            id: 0,
            created_at: 0,
            role: role.to_string(),
            content: vec![db::Block::Text {
                text: text.to_string(),
            }],
            engine: engine.map(|e| e.to_string()),
            agent_id: None,
            agent_name_snapshot: None,
        }
    }

    fn attributed_msg(
        role: &str,
        text: &str,
        engine: Option<&str>,
        agent_id: Option<&str>,
        agent_name_snapshot: Option<&str>,
    ) -> db::Message {
        db::Message {
            id: 0,
            created_at: 0,
            role: role.to_string(),
            content: vec![db::Block::Text {
                text: text.to_string(),
            }],
            engine: engine.map(|e| e.to_string()),
            agent_id: agent_id.map(|id| id.to_string()),
            agent_name_snapshot: agent_name_snapshot.map(|name| name.to_string()),
        }
    }

    fn git_cmd(dir: &std::path::Path, args: &[&str]) {
        let out = std::process::Command::new("git")
            .current_dir(dir)
            .args(args)
            .output()
            .unwrap();
        assert!(
            out.status.success(),
            "git {args:?} failed: {}",
            String::from_utf8_lossy(&out.stderr)
        );
    }

    fn git_out(dir: &std::path::Path, args: &[&str]) -> String {
        let out = std::process::Command::new("git")
            .current_dir(dir)
            .args(args)
            .output()
            .unwrap();
        assert!(
            out.status.success(),
            "git {args:?} failed: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        String::from_utf8_lossy(&out.stdout).trim().to_string()
    }

    fn command_args(cmd: &Command) -> Vec<String> {
        cmd.get_args()
            .map(|arg| arg.to_string_lossy().into_owned())
            .collect()
    }

    fn contains_adjacent_pair(args: &[String], left: &str, right: &str) -> bool {
        args.windows(2)
            .any(|window| window[0] == left && window[1] == right)
    }

    fn env_value(cmd: &Command, key: &str) -> Option<Option<String>> {
        cmd.get_envs()
            .find(|(k, _)| *k == key)
            .map(|(_, v)| v.map(|value| value.to_string_lossy().into_owned()))
    }

    struct TestHome {
        old_home: Option<std::ffi::OsString>,
        _guard: tempfile::TempDir,
        _home_env_guard: std::sync::MutexGuard<'static, ()>,
        path: std::path::PathBuf,
    }

    impl TestHome {
        fn new() -> Self {
            let home_env_guard = crate::worktree::test_home_lock();
            let old_home = std::env::var_os("HOME");
            let guard = tempfile::Builder::new()
                .prefix("agentloom-test-home")
                .tempdir_in("/private/tmp")
                .expect("建测试 HOME 失败");
            let path = guard.path().to_path_buf();
            std::env::set_var("HOME", &path);
            Self {
                old_home,
                _guard: guard,
                _home_env_guard: home_env_guard,
                path,
            }
        }

        fn apply(&self) {
            std::env::set_var("HOME", &self.path);
        }
    }

    impl Drop for TestHome {
        fn drop(&mut self) {
            match &self.old_home {
                Some(home) => std::env::set_var("HOME", home),
                None => std::env::remove_var("HOME"),
            }
        }
    }

    struct EnvOverride {
        key: &'static str,
        old: Option<std::ffi::OsString>,
    }

    impl EnvOverride {
        fn set(key: &'static str, value: &str) -> Self {
            let old = std::env::var_os(key);
            std::env::set_var(key, value);
            Self { key, old }
        }
    }

    impl Drop for EnvOverride {
        fn drop(&mut self) {
            match &self.old {
                Some(value) => std::env::set_var(self.key, value),
                None => std::env::remove_var(self.key),
            }
        }
    }

    fn build_command_with_home_retry<B: AgentBackend>(
        backend: &B,
        ctx: &BuildContext<'_>,
        home: &TestHome,
    ) -> Command {
        let mut last_err = None;
        for _ in 0..10 {
            home.apply();
            match backend.build_command(ctx) {
                Ok(cmd) => return cmd,
                Err(err) if err.contains("Operation not permitted") => {
                    last_err = Some(err);
                    std::thread::yield_now();
                }
                Err(err) => panic!("backend build_command 失败：{err}"),
            }
        }
        panic!(
            "backend build_command 多次遇到 HOME 并发覆盖：{}",
            last_err.unwrap_or_else(|| "unknown".to_string())
        );
    }

    fn build_send_plan_with_home_retry(
        conn: &rusqlite::Connection,
        session_id: &str,
        agent_id: &str,
        message: &str,
        reasoning_tier: Option<&str>,
        key_store: &dyn crate::keychain::KeyStore,
        home: &TestHome,
    ) -> SendPlan {
        let mut last_err = None;
        for _ in 0..10 {
            home.apply();
            match build_send_plan(
                conn,
                session_id,
                "test-run",
                agent_id,
                message,
                reasoning_tier,
                &[],
                key_store,
                Locale::Zh,
            ) {
                Ok(plan) => return plan,
                Err(err) if err.contains("Operation not permitted") => {
                    last_err = Some(err);
                    std::thread::yield_now();
                }
                Err(err) => panic!("build_send_plan 失败：{err}"),
            }
        }
        panic!(
            "build_send_plan 多次遇到 HOME 并发覆盖：{}",
            last_err.unwrap_or_else(|| "unknown".to_string())
        );
    }

