    #[test]
    fn background_stop_notice_persist_failure_is_non_fatal_to_stop() {
        let db = test_db();
        let running = Running::default();
        let team_running = member_runner::TeamRunning::default();
        let session_id = "s-stop-notice-persist-failed";
        running
            .0
            .lock()
            .unwrap()
            .insert(session_id.into(), RunSlot::Running(4324));

        let notice_conn = crate::test_support::mem_db();
        db::create_session(
            &notice_conn,
            session_id,
            "stop notice failure",
            "local-default",
            "local",
        )
        .unwrap();
        notice_conn
            .execute_batch("PRAGMA query_only = ON;")
            .unwrap();

        let killed = std::cell::Cell::new(false);
        let persist_attempted = std::cell::Cell::new(false);
        let emitted = std::cell::Cell::new(false);
        let result = stop_session_with_background_inspection(
            &db,
            &running,
            &team_running,
            session_id,
            Locale::En,
            |pid| {
                assert_eq!(pid, 4324);
                killed.set(true);
            },
            |_, _| Ok(Some("background stop notice".to_string())),
            |notice| {
                persist_attempted.set(true);
                append_background_stop_notice_message(&notice_conn, session_id, notice).map(|_| {
                    emitted.set(true);
                })
            },
            |_| {},
        );

        assert!(result.is_ok(), "落库失败不应让停止流程返回错误：{result:?}");
        assert!(killed.get());
        assert!(persist_attempted.get());
        assert!(!emitted.get(), "落库失败后不应发送未持久化的消息");
        assert!(matches!(
            running.0.lock().unwrap().get(session_id),
            Some(RunSlot::Finalizing {
                stop_requested: true
            })
        ));
    }

    #[test]
    fn agent_argv_and_clean_env() {
        let a = claude_agent_argv("hi");
        assert!(a.iter().any(|s| s == "bypassPermissions"), "{a:?}");
        assert!(
            a.windows(2)
                .any(|w| w[0] == "--setting-sources" && w[1] == "user,project,local"),
            "{a:?}"
        );
        assert!(a.iter().any(|s| s == "hi"), "{a:?}");
        // apply_clean_env 在 get_envs() 把删掉的 key 体现为 (key, None)
        let mut c = std::process::Command::new("claude");
        apply_clean_env(&mut c);
        for k in [
            "ANTHROPIC_API_KEY",
            "ANTHROPIC_BASE_URL",
            "CLAUDE_CODE_OAUTH_TOKEN",
        ] {
            assert!(
                c.get_envs().any(|(kk, v)| kk == k && v.is_none()),
                "应删 {k}"
            );
        }
    }

    #[test]
    fn without_bypass_permissions_strips_the_pair() {
        let argv = claude_agent_argv("hi");
        assert!(argv.iter().any(|s| s == "bypassPermissions"));
        let stripped = without_bypass_permissions(&argv);
        assert!(!stripped.iter().any(|s| s == "bypassPermissions"));
        assert!(!stripped.iter().any(|s| s == "--permission-mode"));
        // 其余参数保留
        assert!(stripped.iter().any(|s| s == "hi"));
        assert!(stripped
            .windows(2)
            .any(|w| w[0] == "--setting-sources" && w[1] == "user,project,local"));
    }

