    #[test]
    fn apply_session_workdir_sets_session_cwd() {
        use crate::test_support::{mem_db, tmp_root};

        let _home_env_guard = crate::worktree::test_home_lock();
        let c = mem_db();
        let session_id = format!("s-cwd-helper-{}", std::process::id());
        let (_home_guard, home) = tmp_root();
        let old_home = std::env::var_os("HOME");
        std::env::set_var("HOME", &home);
        let app_default = home.join(".agentloom").join("local").join("default");
        std::fs::create_dir_all(&app_default).unwrap();
        c.execute(
            "UPDATE repos SET path = ?1 WHERE id = 'local-default'",
            [app_default.to_str().unwrap()],
        )
        .unwrap();
        db::create_session(&c, &session_id, "测试", "local-default", "local").unwrap();
        c.execute(
            "UPDATE sessions SET repo_id = NULL WHERE id = ?1",
            [&session_id],
        )
        .unwrap();

        let mut cmd = Command::new("pwd");
        let wt = apply_session_workdir(&mut cmd, &c, &session_id).expect("helper 不应 err");
        assert!(
            wt.starts_with(crate::worktree::local_sessions_root()),
            "未绑定项目的旧数据应走 app 域 per-session 脚手架"
        );
        assert_ne!(wt, app_default);

        let out = cmd.output().expect("pwd 启动失败");
        assert!(out.status.success(), "pwd 应成功：{:?}", out);
        let stdout = String::from_utf8_lossy(&out.stdout).trim().to_string();

        let wt_canon = std::fs::canonicalize(&wt).unwrap_or_else(|_| wt.clone());
        let pwd_path = std::path::PathBuf::from(stdout);
        let pwd_canon = std::fs::canonicalize(&pwd_path).unwrap_or(pwd_path);
        assert_eq!(
            wt_canon, pwd_canon,
            "pwd 子进程 cwd 应等于 helper 返回的目录"
        );

        let _ = std::fs::remove_dir_all(&wt_canon);
        match old_home {
            Some(v) => std::env::set_var("HOME", v),
            None => std::env::remove_var("HOME"),
        }
    }

    #[test]
    fn stderr_tail_thread_keeps_tail_and_writes_log() {
        let tmp = tempfile::tempdir().unwrap();
        let log_path = tmp.path().join("agent.log");
        let log = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&log_path)
            .unwrap();
        let input = std::io::Cursor::new(format!(
            "{}\nfinal quota failure\n",
            "x".repeat(STDERR_TAIL_LIMIT + 128)
        ));

        let tail = spawn_stderr_tail_thread(input, Some(log)).join().unwrap();

        assert!(tail.contains("final quota failure"), "{tail}");
        assert!(
            tail.len() <= STDERR_TAIL_LIMIT + "final quota failure\n".len(),
            "tail should stay bounded: {}",
            tail.len()
        );
        let logged = std::fs::read_to_string(log_path).unwrap();
        assert!(logged.contains("final quota failure"));
        assert!(logged.starts_with("xxx"));
    }

    #[test]
    fn list_project_files_skips_heavy_dirs_and_keeps_relative_paths() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(tmp.path().join("src")).unwrap();
        std::fs::create_dir_all(tmp.path().join("node_modules/pkg")).unwrap();
        std::fs::create_dir_all(tmp.path().join(".git")).unwrap();
        std::fs::write(tmp.path().join("README.md"), "# Readme\n").unwrap();
        std::fs::write(tmp.path().join("src/main.ts"), "console.log(1)\n").unwrap();
        std::fs::write(tmp.path().join("node_modules/pkg/index.js"), "skip\n").unwrap();
        std::fs::write(tmp.path().join(".git/config"), "skip\n").unwrap();

        let listing = list_project_files(tmp.path()).unwrap();
        let paths: Vec<_> = listing
            .entries
            .iter()
            .map(|entry| entry.path.as_str())
            .collect();

        assert!(paths.contains(&"README.md"), "{paths:?}");
        assert!(paths.contains(&"src"), "{paths:?}");
        assert!(paths.contains(&"src/main.ts"), "{paths:?}");
        assert!(!paths.iter().any(|path| path.starts_with("node_modules")));
        assert!(!paths.iter().any(|path| path.starts_with(".git")));
        assert!(!listing.truncated);
    }

