    /// 验收 d 的强钉法（review 收尾）：`lead_terminal_decision_nonzero_no_terminal` 只能证明
    /// 「决策函数本身在这堆布尔值下算出 EmitError」，证不了「事件循环真的把 saw_blocked/
    /// saw_needs_decision 见证接了线、合成 error 真的喂进了归约器」——lead_terminal_decision
    /// 根本不接受退出码，纯布尔构造下「exit 4 不豁免」恒真、无从测起。改用源码切片钉住调用点
    /// 本身（同款手法见 lead_production_source_does_not_emit_legacy_agent_event）：谁把
    /// record_synthetic_cli_error 那行删掉、或把 lead_terminal_decision 调用点的
    /// saw_blocked/saw_needs_decision 实参改回硬编码 false，这条测试立刻变红。
    #[test]
    fn lead_production_source_wires_synthetic_error_and_blocked_needs_decision_witnesses() {
        let source = include_str!("lib.rs");
        let lead = source
            .split("fn start_lead_session(")
            .nth(1)
            .and_then(|tail| tail.split("\n#[tauri::command]\nfn stop_session(").next())
            .expect("start_lead_session source slice");

        // Bug A：合成 error 必须真正喂进归约器，不能退化回「只造字符串、reducer 从没见过」。
        assert!(
            lead.contains("record_synthetic_cli_error(&mut reducer"),
            "lead 合成 error 必须经 record_synthetic_cli_error 喂进 DisplayReducer"
        );

        // Bug B：lead_terminal_decision 调用点必须真的把 saw_blocked/saw_needs_decision
        // 见证传进去——不能被改回硬编码 false 或漏传参数。
        let call = lead
            .split("let terminal_decision = lead_terminal_decision(")
            .nth(1)
            .and_then(|tail| tail.split(");").next())
            .expect("lead_terminal_decision call-site slice");
        assert!(
            call.contains("saw_blocked"),
            "lead_terminal_decision 调用点必须传 saw_blocked 实参: {call}"
        );
        assert!(
            call.contains("saw_needs_decision"),
            "lead_terminal_decision 调用点必须传 saw_needs_decision 实参: {call}"
        );
    }

    /// G3-A T2 结构钉子（同款手法：`lead_production_source_wires_synthetic_error_and_
    /// blocked_needs_decision_witnesses`）：`start_lead_session` 是巨型 `#[tauri::command]`
    /// 闭包·真跑一次要 spawn 真进程，测不动其内部逐行 wiring，只能钉源码切片。
    /// 钉两件事：① lead 自己 stdout 里的 Completed usage 必须被捕获进 `lead_completed_usage`
    /// （不能被静默删掉退回「lead run 恒 0」）；② 收尾处必须真调 `add_session_usage` 落库
    /// （且只应出现一次——双记账钉在下面的计数断言）。
    #[test]
    fn lead_production_source_wires_usage_capture_and_persist() {
        let source = include_str!("lib.rs");
        let lead = source
            .split("fn start_lead_session(")
            .nth(1)
            .and_then(|tail| tail.split("\n#[tauri::command]\nfn stop_session(").next())
            .expect("start_lead_session source slice");

        assert!(
            lead.contains("lead_completed_usage = Some((*input_tokens, *output_tokens))"),
            "lead 事件循环必须从 stdout 流里的 Completed 事件捕获 usage 到 lead_completed_usage"
        );

        let usage_call_count = lead
            .matches("db::add_session_usage(&conn, &session_id_t")
            .count();
        assert_eq!(
            usage_call_count, 1,
            "lead run 落账必须恰好一次调用 add_session_usage（防双记账），实际 {usage_call_count} 次"
        );

        // 落账必须门在 `lead_completed_usage` 之上——不能改成恒定落 0/None，也不能绕过
        // lead_completed_usage 直接从别处硬编码调用（防止「调用存在但素材来源被偷换」）。
        // 用「守卫行到调用行之间距离足够近」代替脆弱的「之间不含 fn」全文扫描。
        let guard = "if let Some((input_tokens, output_tokens)) = lead_completed_usage";
        let guard_pos = lead.find(guard).expect("usage guard site");
        let call_pos = lead
            .find("db::add_session_usage(&conn, &session_id_t")
            .expect("usage call site");
        assert!(
            call_pos > guard_pos && call_pos - guard_pos < 400,
            "add_session_usage 落库必须紧跟在 `if let Some(...) = lead_completed_usage` 守卫之内（guard@{guard_pos} call@{call_pos}）"
        );
    }

    #[test]
    fn stage1_relay_worker2_sees_worker1_and_user_main_stays_clean() {
        use crate::worktree;
        let _home_lock = worktree::test_home_lock();
        let home_tmp = tempfile::tempdir().unwrap();
        struct HomeVarGuard {
            old: Option<std::ffi::OsString>,
        }
        impl HomeVarGuard {
            fn set(path: &std::path::Path) -> Self {
                let old = std::env::var_os("HOME");
                std::env::set_var("HOME", path);
                Self { old }
            }
        }
        impl Drop for HomeVarGuard {
            fn drop(&mut self) {
                match &self.old {
                    Some(v) => std::env::set_var("HOME", v),
                    None => std::env::remove_var("HOME"),
                }
            }
        }
        let _home_var = HomeVarGuard::set(home_tmp.path());

        // Create base repo with initial commit
        let repo_tmp = tempfile::tempdir().unwrap();
        let repo = repo_tmp.path().to_path_buf();
        let git = |dir: &std::path::Path, args: &[&str]| {
            std::process::Command::new("git")
                .current_dir(dir)
                .args(args)
                .output()
                .unwrap()
        };
        git(&repo, &["init", "-q"]);
        git(&repo, &["config", "user.email", "t@t"]);
        git(&repo, &["config", "user.name", "t"]);
        git(&repo, &["config", "commit.gpgsign", "false"]);
        std::fs::write(repo.join("seed.md"), "seed").unwrap();
        git(&repo, &["add", "seed.md"]);
        git(
            &repo,
            &[
                "-c",
                "user.email=t@t",
                "-c",
                "user.name=t",
                "commit",
                "-q",
                "-m",
                "base",
            ],
        );
        worktree::mark_test_app_domain(&repo);
        let base_master_sha = worktree::rev_parse_head(&repo).unwrap();

        let session_id = "relay-integ";
        let session_wt = worktree::ensure_workspace(session_id, Some(&repo), false).unwrap();

        // --- Worker 1 ---
        let member1_wt =
            worktree::ensure_member_workspace(session_id, "w1", Some(&repo), false).unwrap();
        let base_sha1 = worktree::rev_parse_head(&member1_wt).unwrap();
        std::fs::write(member1_wt.join("a.md"), "worker1").unwrap();
        git(&member1_wt, &["add", "a.md"]);
        git(
            &member1_wt,
            &[
                "-c",
                "user.email=t@t",
                "-c",
                "user.name=t",
                "commit",
                "-q",
                "-m",
                "worker1",
            ],
        );
        let member1_branch = format!("agentloom/{}-m-w1", worktree::safe_id(session_id));
        let ctx1 = crate::member_runner::Stage1Ctx {
            session_wt: session_wt.clone(),
            member_wt: member1_wt.clone(),
            member_branch: member1_branch.clone(),
        };
        let sha1 = match crate::member_runner::run_stage1(&ctx1, "run1", &base_sha1, true) {
            crate::member_runner::Stage1Result::Relayed { session_head } => session_head,
            other => panic!("worker1 应 Relayed·实得 {other:?}"),
        };
        assert!(
            session_wt.join("a.md").exists(),
            "会话 wt 应含 a.md 后 worker1 Stage①"
        );
        assert_ne!(sha1, base_master_sha);

        // --- Worker 2 派生自会话分支（接力起点）---
        let member2_wt =
            worktree::ensure_member_workspace(session_id, "w2", Some(&repo), false).unwrap();
        assert!(member2_wt.join("a.md").exists(), "worker2 接力应看到 a.md");
        let base_sha2 = worktree::rev_parse_head(&member2_wt).unwrap();
        std::fs::write(member2_wt.join("a.md"), "worker2").unwrap();
        git(&member2_wt, &["add", "a.md"]);
        git(
            &member2_wt,
            &[
                "-c",
                "user.email=t@t",
                "-c",
                "user.name=t",
                "commit",
                "-q",
                "-m",
                "worker2",
            ],
        );
        let member2_branch = format!("agentloom/{}-m-w2", worktree::safe_id(session_id));
        let ctx2 = crate::member_runner::Stage1Ctx {
            session_wt: session_wt.clone(),
            member_wt: member2_wt.clone(),
            member_branch: member2_branch.clone(),
        };
        let sha2 = match crate::member_runner::run_stage1(&ctx2, "run2", &base_sha2, true) {
            crate::member_runner::Stage1Result::Relayed { session_head } => session_head,
            other => panic!("worker2 应 Relayed·实得 {other:?}"),
        };
        assert!(session_wt.join("a.md").exists());
        assert_ne!(sha2, sha1);

        // 不变量：用户 repo master HEAD 不动
        let user_head = worktree::rev_parse_head(&repo).unwrap();
        assert_eq!(user_head, base_master_sha, "用户 repo master HEAD 不得变动");

        // 不变量：用户 repo 只有 agentloom/* 分支
        let out = std::process::Command::new("git")
            .current_dir(&repo)
            .args(["branch", "--format=%(refname:short)"])
            .output()
            .unwrap();
        let branches = String::from_utf8_lossy(&out.stdout).to_string();
        // The initial default branch (master/main) is fine - only extra branches must be agentloom/*
        for b in branches.lines().filter(|b| !b.trim().is_empty()) {
            assert!(
                b.starts_with("agentloom/") || b == "master" || b == "main",
                "意外的非 agentloom 分支：{b}"
            );
        }

        // Cleanup
        let _ = git(
            &repo,
            &[
                "worktree",
                "remove",
                "--force",
                session_wt.to_str().unwrap(),
            ],
        );
        let _ = git(
            &repo,
            &[
                "worktree",
                "remove",
                "--force",
                member1_wt.to_str().unwrap(),
            ],
        );
        let _ = git(
            &repo,
            &[
                "worktree",
                "remove",
                "--force",
                member2_wt.to_str().unwrap(),
            ],
        );
        let _ = git(&repo, &["worktree", "prune"]);
    }

